-- VDI-3814-Blatt-2-1-01 · standard_geltungsbereich
update public.fields set verification_status='verified_against_standard', verification_quote='Die Richtlinienreihe VDI 3814 gilt für die Automation von Gebäuden und Immobilienportfolios. Da die GA dort fachübergreifend die Funktionalität aller Räume (Raumautomation) und Anlagen (Anlagenautomation) inklusive der Managementfunktionen während deren Betrieb und Nutzung bestimmt, gilt diese Richtlinie somit in den Bereichen jener Gewerke, deren Funktionalität durch GA, auch teilweise, erzielt wird [...] — printed p.4', verification_note='md-verified 2026-09-05 (§1, printed p.4) [VC]', verified_at=now() where id='ba3f9398-8a3d-4e48-8e50-c614dca5fa8b' and verification_status not in ('verified_against_standard','corrected');
