update public.fields set verification_status='verified_against_standard', verification_quote='Planungshandbuch Bestandteil des zwischen dem Fachplaner (Auftragnehmer – AN) und dem Auftraggeber (AG) geschlossenen Vertrags, der die Grundlage der planerischen Vorgaben des jeweiligen Gewerks beschreibt | Anmerkung 2: Ein Planungshandbuch im Bereich der GA/ Systemintegration muss (z. B. in einem Baukasten) eine makrobasierende Darstellung der einzusetzenden/auszuwählenden Systeme, Automationseinrichtungen, Feldgeräte, Kommunikationsprotokolle und GA-Funktionen beinhalten. — printed p.4-5', verification_note='md-verified 2026-09-05 (§3, printed p.4-5) [VC]', verified_at=now() where id='fb8c57bd-14e6-4dcb-b84d-0ad50b1c92c2' and verification_status not in ('verified_against_standard','corrected');
