update public.fields set verification_status='verified_against_standard', verification_quote='Anlagen, die für die Gebäude-/Bereichsversorgung zuständig sind (z. B. Kälteversorgung Rechenzentrum), sind mit einer Anlagenpriorität zu versehen, die mindestens der Gebäudepriorität entspricht. | Die Anlagenprioritäten sind vor oder spätestens mit Beginn einer Planung mit dem AG abzustimmen. Die Anlagenpriorität kann z . B. in drei Stufen unterschieden werden [...] | hoch | mittel | niedrig — printed p.18-19', verification_note='md-verified 2026-09-05 (§7.7.1, printed p.18-19) [VC]', verified_at=now() where id='1941514b-58a4-4ef3-9a37-c68b674db8ad' and verification_status not in ('verified_against_standard','corrected');
-- VDI-3814-Blatt-2-1-03 · sla_definition
update public.fields set verification_status='verified_against_standard', verification_quote='Das zentrale Element dieser Dienstgütevereinbarung ist die Leistungsqualität (z. B. Verfügbarkeit einer klimatechnischen Anlage von 99,98 %). | Folgende Inhalte und Ziele sind in Bezug auf die Erfüllung der vereinbarten Dienstleistungen zwischen AG und AN festzulegen und beeinflussen mittelbar den Einsatz und das Ausmaß der GA: | Rollen, Leistungsbeiträge und Verantwortlichkeiten der Beteiligten | Parameter zur Beurteilung der Dienstleistungsqualität | Prozedur zur Schlichtung von Meinungsunterschieden zwischen den Vertragspartnern — printed p.19', verification_note='md-verified 2026-09-05 (§7.7.2, printed p.19) [VC] — the 99,98 % is an explicit "z. B." example, NOT a normative availability limit', verified_at=now() where id='131c3d2c-6427-4778-9fb1-3ae243c8157c' and verification_status not in ('verified_against_standard','corrected');
-- VDI-3814-Blatt-2-1-03 · performance_indikatoren
update public.fields set verification_status='verified_against_standard', verification_quote='Zur Kontrolle der Erreichung dieser Zielvorgaben gemäß der SLA werden Leistungserfüllungsindikatoren („performance indicators") verwendet, die mittels der GA überwacht und dem TGM zur Verfügung gestellt werden können, siehe auch VDI 3810 Blatt 5. — printed p.20', verification_note='md-verified 2026-09-05 (§7.7.2, printed p.20) [VC] — descriptive/optional ("können") — is_required=false is source-consistent', verified_at=now() where id='7c092551-8ea1-4916-ad6f-7093887a7fd5' and verification_status not in ('verified_against_standard','corrected');
-- VDI-3814-Blatt-2-1-04 · lastenheft_erstellt
update public.fields set verification_status='verified_against_standard', verification_quote='Ein GA-Lastenheft stellt die Anforderungen des AG hinsichtlich Bedarf, Nutzung, Liefer- und Leistungsplanung dar und wird sinnvollerweise im Rahmen der Bedarfsplanung oder parallel dazu erstellt. Die Ergebnisse einer Bedarfsplanung sind sinnvollerweise in einem Lastenheft zu dokumentieren. — printed p.20', verification_note='md-verified 2026-09-05 (§8.1, printed p.20) [VC] — soft ("sinnvollerweise"); §8.1 explicitly allows dispensing with a Lastenheft ("Beim Verzicht auf die Erstellung/Verwendung von GA-Lastenheften ...") — see STAGED file', verified_at=now() where id='fc9978b0-ef39-4a9c-8aa5-b54ec69f2e3e' and verification_status not in ('verified_against_standard','corrected');
-- VDI-3814-Blatt-2-1-04 · redundanz_vorgaben
update public.fields set verification_status='verified_against_standard', verification_quote='Grundsätzlich sind zusätzlich zu den Festlegungen in Abschnitt 8.2 bis Abschnitt 8.14 die folgenden Aspekte zu beachten: | Vorgaben an notwendige Redundanzen für alle Bereiche der GA-Systeme — printed p.21', verification_note='md-verified 2026-09-05 (§8.1, printed p.21) [VC]', verified_at=now() where id='039e2fb0-8224-468a-9b07-185515bd51ea' and verification_status not in ('verified_against_standard','corrected');
-- VDI-3814-Blatt-2-1-04 · mech_elektr_umgebung
update public.fields set verification_status='verified_against_standard', verification_quote='Grundsätzlich sind zusätzlich zu den Festlegungen in Abschnitt 8.2 bis Abschnitt 8.14 die folgenden Aspekte zu beachten: [...] | einzuhaltende Merkmale hinsichtlich der Mechanik, Elektrik und der Umgebungsbedingun- gen, z. B. Schutzklassen, EMV, Überspannungsschutz und gegebenenfalls Ex-Schutz — printed p.21', verification_note='md-verified 2026-09-05 (§8.1, printed p.21) [VC]', verified_at=now() where id='bb93fa4a-b0bf-46d8-8004-80e708a1da39' and verification_status not in ('verified_against_standard','corrected');
-- VDI-3814-Blatt-2-1-04 · datenkommunikationsprotokoll
update public.fields set verification_status='verified_against_standard', verification_quote='Die funktionale, interoperable Verbindung von Einrichtungen der Raum- und Anlagenautomation, der Management- und Bedieneinrichtungen sowie zu Einrichtungen für besondere Anwendungen erfolgt mittels Kommunikationseinrichtungen, für die genormte Datenkommunikationsprotokolle vorgegeben werden sollen. | Welche Datenkommunikationsprotokolle sind eingesetzt/sollen eingesetzt werden (BACnet, KNX, Dali usw.)? — printed p.22 | p.13', verification_note='md-verified 2026-09-05 (§8.2.1 (protocol obligation) + §7.2 (the BACnet/KNX/DALI list), printed p.22 and p.13) [VC] — the three enum values are NOT printed in §8.2.1; they come from the §7.2 checklist question and that list is open ("usw.") — see STAGED file', verified_at=now() where id='28082bd0-c433-411e-b104-1dc1e4e6cf4d' and verification_status not in ('verified_against_standard','corrected');
-- VDI-3814-Blatt-2-1-04 · datenschnittstellen
update public.fields set verification_status='verified_against_standard', verification_quote='Die Art und Anzahl der zu verwendenden Datenschnittstellen sind zu spezifizieren. Insbesondere ist die erforderliche Interoperabilität der beteiligten Teilsysteme eindeutig festzulegen. Hierbei sind insbesondere die Datenschnittstellen zu Management- und Bedieneinrichtungen, Anlagen- und Raumautomationseinrichtungen, Feldgeräten, autarken Automationseinrichtungen und eventuellen Systemen für besondere Aufgaben zu spezifizieren. — printed p.22', verification_note='md-verified 2026-09-05 (§8.2.2, printed p.22) [VC]', verified_at=now() where id='52963d8c-01ed-42ef-8587-8d716c4b4a9a' and verification_status not in ('verified_against_standard','corrected');
-- VDI-3814-Blatt-2-1-04 · meldungsart
update public.fields set verification_status='verified_against_standard', verification_quote='Die Meldungen innerhalb des GA-Systems sind je nach Ursache, Art und/oder Auswirkung in verschiedene Gruppen zu unterteilen, z. B.: | Gefahrmeldungen | Sicherheitsmeldungen | Systemmeldungen | Störungsmeldungen | Warn-/Wartungsmeldungen | Handmeldungen | Trendlogmeldungen — printed p.22', verification_note='md-verified 2026-09-05 (§8.3.1, printed p.22) [VC] — list is exemplary ("z. B."); the encoded enum reproduces exactly these 7 and adds none', verified_at=now() where id='e5c7fca3-061b-4fa8-a658-cece7a5324b6' and verification_status not in ('verified_against_standard','corrected');
-- VDI-3814-Blatt-2-1-04 · meldungsuebertragung
update public.fields set verification_status='verified_against_standard', verification_quote='Die Automationsstationen (AS) sowie die Management- und Bedieneinrichtungen (MBE) im GA-System unterstützen die Alarm- und Ereignisbehandlung als Sender/Empfänger mit den folgenden Diensten: | Melden von Wert- und Zustandsänderungen | objektinternes Melden [...] | gegebenenfalls zusätzliches erweitertes Melden [...] | Die zu verwendende Art der Meldungsübertragung oder Kombinationen der oben genannten Verfahren sind mit dem AG abzustimmen. — printed p.23', verification_note='md-verified 2026-09-05 (§8.3.2, printed p.23) [VC]', verified_at=now() where id='57314f9a-8061-4e1f-8dba-b42069e40631' and verification_status not in ('verified_against_standard','corrected');
-- VDI-3814-Blatt-2-1-04 · meldungsempfaenger
update public.fields set verification_status='verified_against_standard', verification_quote='Die erforderlichen Meldungsempfänger sind mit dem AG zu definieren und die Übertragungswege zu spezifizieren. — printed p.23', verification_note='md-verified 2026-09-05 (§8.3.3, printed p.23) [VC]', verified_at=now() where id='8b1a169a-081f-479a-9690-7eead248a4a7' and verification_status not in ('verified_against_standard','corrected');
-- VDI-3814-Blatt-2-1-04 · meldung_zustandsuebergang
update public.fields set verification_status='verified_against_standard', verification_quote='Hierbei sind mindestens die Prioritäten für die verschiedenen Zustandsübergänge, z. B. „Meldung kommend", „Meldung gehend", „Systemmeldung", zu spezifizieren. — printed p.23', verification_note='md-verified 2026-09-05 (§8.3.3, printed p.23) [VC] — the three transitions are an explicit "z. B." list — the encoded enum closes an open list', verified_at=now() where id='a070ced1-df46-451b-80ce-c27a94677395' and verification_status not in ('verified_against_standard','corrected');
-- VDI-3814-Blatt-2-1-04 · meldungsquittierung
update public.fields set verification_status='verified_against_standard', verification_quote='Die Quittierungserfordernisse durch die Meldungsempfänger sind eindeutig festzulegen. Eine Notwendigkeit der Quittierung von Meldungen kann z. B. nur für bestimmte Meldungsarten, wie Störungs-, Handeingriff- und Warnmeldungen, oder aber auch für bestimmte Zustandsübergänge spezifiziert werden. — printed p.23', verification_note='md-verified 2026-09-05 (§8.3.4, printed p.23) [VC]', verified_at=now() where id='bbd31b30-62ce-4851-b6d9-f61a96c4c421' and verification_status not in ('verified_against_standard','corrected');
-- VDI-3814-Blatt-2-1-05 · feldgeraete_spezifikation
update public.fields set verification_status='verified_against_standard', verification_quote='Die Arten der zu verwendenden Sensoren und Aktoren sowie deren Merkmale sind gemäß den Anforderungen zu spezifizieren, z. B.: | kombinierte Sensoren | Genauigkeit | Bauform | Größe — printed p.24', verification_note='md-verified 2026-09-05 (§8.4, printed p.24) [VC]', verified_at=now() where id='9dc0a5c4-2ada-4f8d-8f34-07ad4c3413da' and verification_status not in ('verified_against_standard','corrected');
-- VDI-3814-Blatt-2-1-05 · automationseinrichtungen_spez
update public.fields set verification_status='verified_against_standard', verification_quote='Automationseinrichtungen (siehe auch DIN EN ISO 16484-2, Abschnitt 5.3) beinhalten sämtliche parametrierbaren, projektierbaren oder programmierbaren GA-Systemkomponenten für die Anlagen- und Raumautomation. Für diese sind neben dem zu verwendenden Datenkommunikationsprotokoll und der notwendigen Datenschnittstelleneinheiten eventuell zusätzlich notwendige Speicheranforderungen und die Art der manuellen Übersteuerungsmöglichkeiten festzulegen. — printed p.24', verification_note='md-verified 2026-09-05 (§8.5, printed p.24) [VC]', verified_at=now() where id='f125a33f-ebd3-4371-876f-a5f7d66c53d0' and verification_status not in ('verified_against_standard','corrected');
-- VDI-3814-Blatt-2-1-05 · projektierungstools
update public.fields set verification_status='verified_against_standard', verification_quote='Es ist mit dem AG/Nutzer festzulegen, welche Arten der projektierungs- und sonstigen system- spezifischen technischen Dienstleistungen innerhalb des GA-Systems erforderlich werden, z. B.: | Konfigurierung der Hardware | Programmierung der Anwendungsfunktionen | Konfigurierung der Management- und Bedienfunktionen | Hierfür ist zwischen dem AN und dem AG eine Übergabe/Überlassung der hierfür erforderlichen herstellerspezifischen Tools zu vereinbaren. — printed p.24', verification_note='md-verified 2026-09-05 (§8.5.1, printed p.24) [VC]', verified_at=now() where id='4ced3c64-217b-45e4-b0fc-790782d4337f' and verification_status not in ('verified_against_standard','corrected');
-- VDI-3814-Blatt-2-1-05 · verhalten_spannungsausfall
update public.fields set verification_status='verified_against_standard', verification_quote='Alle Folgen und Reaktionen im GA-System, die sich aus einem Versorgungsspannungsausfall und Wiederkehr ergeben, sind festzulegen, z. B.: | Meldungsunterdrückung bei Spannungsausfall | Vorgaben zur Pufferung und Sicherung von flüchtigen Speicherinhalten | Nutzung von Vorgabewerten (Defaultwerte) — printed p.24', verification_note='md-verified 2026-09-05 (§8.5.2, printed p.24) [VC]', verified_at=now() where id='08002991-b10a-47f0-967b-b1ebe127f6b3' and verification_status not in ('verified_against_standard','corrected');
-- VDI-3814-Blatt-2-1-05 · mbe_systemart
update public.fields set verification_status='verified_against_standard', verification_quote='Hierbei sind neben der Art des vorgesehenen Systems (webbasierendes oder Rich-Client-System oder beides) und den eventuell vorgegebenen und einzuhaltenden Betriebssystemen u. a. zu berücksichtigen: — printed p.25', verification_note='md-verified 2026-09-05 (§8.6, printed p.25) [VC]', verified_at=now() where id='8041f900-71e1-4432-ab06-91eca160c525' and verification_status not in ('verified_against_standard','corrected');
-- VDI-3814-Blatt-2-1-05 · mbe_anforderungen
update public.fields set verification_status='verified_against_standard', verification_quote='Hierbei sind neben der Art des vorgesehenen Systems [...] u. a. zu berücksichtigen: | Applikationen der MBE | Lizenzierung | Benutzermanagement (Benutzer-/Systemverwaltung) | grafische Benutzeroberfläche [...] | Trends | Listen | Zeit-/Kalendermanagement | Bedienung von Datenpunkten | Berichts-, Protokoll- und Reportmanagement | Sicherungs- und Rücksicherungsmanagement (Backup und Restore) | Energiemonitoring/Energiemanagement | MBE-Serverstandort | MBE-Server- und -Client-Hardware | Wartung und Pflege der MBE-Software — printed p.25', verification_note='md-verified 2026-09-05 (§8.6, printed p.25) [VC]', verified_at=now() where id='af331958-69e0-459f-93ce-ea4bec39520f' and verification_status not in ('verified_against_standard','corrected');
-- VDI-3814-Blatt-2-1-05 · schaltschrank_anforderungen
update public.fields set verification_status='verified_against_standard', verification_quote='Bei den Anforderungen an die Schaltschränke der GA und deren Baugruppen sind u. a. die nachfolgenden Punkte zu berücksichtigen: | Bauweise, Ausführung des Gehäuses (z. B. Farbton) | Montageplatten | Trennung, Schottung Schaltschrank | Türen, Sichttüren und Sichtfenster sowie deren Verschlüsse [...] | Schutzarten und Ausführung der Schutzmaßnahmen [...] | Netzeinspeisung [...] | Überspannungsschutz [...] | Verdrahtung, Leiterfarben | Platzreserve, maximale Füllung (in %) des Kabelkanals — printed p.25-26', verification_note='md-verified 2026-09-05 (§8.7, printed p.25-26) [VC]', verified_at=now() where id='b78900e5-ffc5-457b-89c4-729b046731f2' and verification_status not in ('verified_against_standard','corrected');
-- VDI-3814-Blatt-2-1-05 · it_netzwerk_anforderungen
update public.fields set verification_status='verified_against_standard', verification_quote='Es ist zu klären, ob ein separates GA-Netzwerk aufgebaut/genutzt wird oder ob eine Integration in ein vorhandenes Unternehmensnetzwerk erfolgen soll. Dies gilt auch für alle im GA-System notwendigen IT-Systeme/Infrastrukturkomponenten [...] Daraus folgend sind Vorgaben für die GA-relevanten IT-Systeme und Netzwerke festzulegen, z. B.: | Installationsanforderungen [...] | Netzwerkmanagement [...] | Verfügbarkeit und Zuverlässigkeit [...] | Hardware- und Softwarevorgaben — printed p.26-27', verification_note='md-verified 2026-09-05 (§8.8, printed p.26-27) [VC]', verified_at=now() where id='df01b3a9-52c4-4867-9522-edf8b50d4a65' and verification_status not in ('verified_against_standard','corrected');
-- VDI-3814-Blatt-2-1-05 · it_sicherheit
update public.fields set verification_status='verified_against_standard', verification_quote='Daraus folgend sind Vorgaben für die GA-relevanten IT-Systeme und Netzwerke festzulegen, z. B.: [...] | IT-Sicherheit (siehe auch VDMA 24774) | Herstellerebene | Projektierungsebene | Inbetriebnahmeebene | Wartungsebene | Fernservice | Benutzerebene — printed p.26-27', verification_note='md-verified 2026-09-05 (§8.8, printed p.26-27) [VC] — IT-Sicherheit appears only as a bullet inside an exemplary ("z. B.") list — see STAGED file', verified_at=now() where id='d2a2e9fc-3070-44ae-b61c-035edcc34991' and verification_status not in ('verified_against_standard','corrected');
-- VDI-3814-Blatt-2-1-06 · ga_funktionen
update public.fields set verification_status='verified_against_standard', verification_quote='Die Funktionen der GA werden in VDI 3814 Blatt 3.1 und VDI 3814 Blatt 3.2 beschrieben. Die Auswahl und Verwendung der Funktionen ist in Abhängigkeit von der beschriebenen Automationsaufgabe vorzunehmen. Hilfsmittel dazu werden in VDI 3814 Blatt 4.3 angeboten. — printed p.27', verification_note='md-verified 2026-09-05 (§8.9, printed p.27) [VC] — the function catalogue itself lives in VDI 3814 Blatt 3.1/3.2 — NR from this Blatt', verified_at=now() where id='c3de2a94-b86a-4fd4-b247-756857b79aa6' and verification_status not in ('verified_against_standard','corrected');
-- VDI-3814-Blatt-2-1-06 · energieeffizienzklasse
update public.fields set verification_status='verified_against_standard', verification_quote='Die anzustrebende Energieeffizienzklasse gemäß DIN EN 15232 ist festzulegen. — printed p.27', verification_note='md-verified 2026-09-05 (§8.10, printed p.27-28) [VC] — the class values (A/B/C/D) are defined in DIN EN 15232, not here — NR from this Blatt', verified_at=now() where id='69e81e36-5938-489e-85fc-5dfc517c883c' and verification_status not in ('verified_against_standard','corrected');
-- VDI-3814-Blatt-2-1-06 · historisierung_vorgaben
update public.fields set verification_status='verified_against_standard', verification_quote='Die notwendigen Vorgaben bezüglich der Historisierung der Datenspeicherung sind festzulegen, insbesondere wenn es Anforderungen an die historische Speicherdauer gibt oder die Daten gegen jegliche Veränderung zu schützen sind (Audit Trail). Dabei ist mindestens die Art der Speicherung unter Beachtung eventueller Datenbegrenzungen und der zu verwendenden Speichermedien zu definieren. — printed p.28', verification_note='md-verified 2026-09-05 (§8.11, printed p.28) [VC]', verified_at=now() where id='56a6d0bd-861e-4835-8910-4b2e502d40a2' and verification_status not in ('verified_against_standard','corrected');
-- VDI-3814-Blatt-2-1-06 · aufzeichnung_aufloesung
update public.fields set verification_status='verified_against_standard', verification_quote='Für alle zu erfassenden und aufzuzeichnenden Größen sind die einzustellenden Auflösungen bezogen auf die zugehörigen Einheiten (z. B. 0,1 °C bei Temperaturaufzeichnungen) sowie die Genauigkeit der Zeitstempel vorzugeben. [...] Typische Auflösungen sind Tabelle 1 zu entnehmen. | Tabelle 1. Beispiele für Auflösungen zu erfassender Größen — Messgröße Auflösung Einheit — Raum-/Außentemperatur 0,1 °C — Druck 0,01 bar — Energie – Strom 0,1 Wh — CO2 10 ppm — printed p.28-29', verification_note='md-verified 2026-09-05 (§8.11 / Tabelle 1, printed p.28-29) [VC] — Tabelle 1 is explicitly captioned "Beispiele" — the resolutions are exemplary, not normative limits; is_required=false is source-consistent', verified_at=now() where id='782f9bc0-2982-4e18-a6d1-3c7f6d08ee59' and verification_status not in ('verified_against_standard','corrected');
-- VDI-3814-Blatt-2-1-06 · cafm_schnittstellen
update public.fields set verification_status='verified_against_standard', verification_quote='Bei der Bedarfsplanung der GA ist grundsätzlich eine Prüfung von Schnittstellen zu anderen Systemen des CAFM zu berücksichtigen. [...] Diese Schnittstellen sind im Rahmen der Planung der GA systematisch zu beschreiben. Dabei sind die Anforderungen des CAFM an die GA zu berücksichtigen. — printed p.29', verification_note='md-verified 2026-09-05 (§8.12, printed p.29) [VC]', verified_at=now() where id='6a78de40-50ed-449b-98ae-8771f083871f' and verification_status not in ('verified_against_standard','corrected');
-- VDI-3814-Blatt-2-1-06 · systemselbstueberwachung
update public.fields set verification_status='verified_against_standard', verification_quote='Für jedes Projekt sind Anforderungen an die Funktionen der Systemselbstüberwachung und an die Systemreaktionen von Feldgeräten, Automations- sowie Management- und Bedieneinrichtungen im Fehlerfall festzulegen. Für die Überwachung (z. B. Sensorüberwachung, Watchdog-Funktion, Netzwerkkommunikation) und Diagnose (z. B. mittels Protokoll-Analyser) sind bei Bedarf geeignete Funktionen und Hilfsmittel vorzusehen. — printed p.30', verification_note='md-verified 2026-09-05 (§8.13.1, printed p.30) [VC]', verified_at=now() where id='fe50794d-106d-4311-b9b0-026c5502d42b' and verification_status not in ('verified_against_standard','corrected');
-- VDI-3814-Blatt-2-1-06 · systemzeitverwaltung
update public.fields set verification_status='verified_against_standard', verification_quote='Die Verwaltungsmethoden hinsichtlich Uhrzeit, Datum, Kalender und Zeitzonen sind f ür das gesamte GA-System einheitlich anzugeben. Dabei sind mindestens folgende Punkte festzulegen: | Art der Uhr (Funkuhr, interne oder externe Zeitserver usw.) | externe/interne Uhr und Übernahme bei Teilausfällen | Auflösung und Genauigkeit der Systemzeit | Synchronisation der Zeit im Gesamtsystem | Nutzung unterschiedlicher Zeitzonen und Sommer-/Winterzeitumschaltung | Anpassung von Uhrzeit, Datum, Zeitzonen — printed p.30', verification_note='md-verified 2026-09-05 (§8.13.2, printed p.30) [VC]', verified_at=now() where id='b1160305-fb7b-47fe-8c45-ec0a28058149' and verification_status not in ('verified_against_standard','corrected');
-- VDI-3814-Blatt-2-1-06 · datenimport_export
update public.fields set verification_status='verified_against_standard', verification_quote='Die notwendigen Datenimport funktionen und Datenexportfunktionen sind eindeutig für alle relevanten Schnittstellen des GA-Systems (z. B. Systeme für besondere Aufgaben) festzulegen. — printed p.30', verification_note='md-verified 2026-09-05 (§8.13.3, printed p.30) [VC]', verified_at=now() where id='95307fb2-aca4-463a-9b8c-29b9baeb431e' and verification_status not in ('verified_against_standard','corrected');
-- VDI-3814-Blatt-2-1-06 · zugriffsebene
update public.fields set verification_status='verified_against_standard', verification_quote='Um das System vor Missbrauch zu sch ützen, müssen mehrere Zugriffsebenen, die in Profilen definiert sind, f ür alle dialogorientierten Bedienerschnittstellen zur Verf ügung stehen. Die Anzahl und Bedeutung dieser Zugriffsebenen sind festzulegen, z. B.: | kein Passwort | nur Lesen | beschränkter Zugriff auf ausgewählte Informationen | Ebene 1 | Es ist nur tägliche Routinebedienung erlaubt. | Ebene 2 | Zugriff des Bedieners auf alle nicht konfigurierbaren Funktionen | Ebene 3 | Bearbeitungszugriff, erforderlich zur Konfigurierung des gesamten Systems — printed p.30-31', verification_note='md-verified 2026-09-05 (§8.13.4, printed p.30-31) [VC] — the four levels are an explicit "z. B." list — the encoded enum closes an open list', verified_at=now() where id='925edbd8-54f3-4c61-9313-b059f9b43542' and verification_status not in ('verified_against_standard','corrected');
-- VDI-3814-Blatt-2-1-06 · aktivitaetenspeicher
update public.fields set verification_status='verified_against_standard', verification_quote='Es ist festzulegen, in welcher Form System-, Ereignis- sowie Bedieneraktivitäten und gegebenenfalls zusätzliche Nutzerdaten aufzuzeichnen und zu speichern sind. Der Umfang der aufzuzeichnenden Bedienvorgänge für nachfolgendes Anzeigen auf einem Bildschirm, Ausdrucken und Archivieren ist festzulegen. [...] Hierbei sind der gesetzliche Datenschutz und die Datenschutzvorgaben des jeweiligen AG zu beachten. — printed p.31', verification_note='md-verified 2026-09-05 (§8.13.5, printed p.31) [VC]', verified_at=now() where id='eeb0a8a4-9a32-4278-a3d1-175a688b876e' and verification_status not in ('verified_against_standard','corrected');
-- VDI-3814-Blatt-2-1-06 · datensicherung_konzept
update public.fields set verification_status='verified_against_standard', verification_quote='Der Prozess zum Erstellen einer Sicherung sowie das Verifizieren und Rekonstruieren des Datenbestands müssen Bestandteil der Systembeschreibung der GA sein und sind einheitlich vorzugeben. [...] Die Art und die Zykluszeiten der erforderlichen Sicherungen sind zu definieren. | Es ist ein Konzept vorzusehen, wie die aufgezeichneten Daten dauerhaft archiviert werden. — printed p.31-32', verification_note='md-verified 2026-09-05 (§8.13.6, printed p.31-32) [VC]', verified_at=now() where id='3646b912-9436-4b49-9682-ee4a812426be' and verification_status not in ('verified_against_standard','corrected');
-- VDI-3814-Blatt-2-1-06 · fernzugriff
update public.fields set verification_status='verified_against_standard', verification_quote='Alle Einrichtungen und Funktionen, die zur Fernbedienung des GA-Systems eingesetzt werden sollen, sind vorzugeben. Hierbei sind insbesondere die Sicherheitsvorgaben zu berücksichtigen. — printed p.32', verification_note='md-verified 2026-09-05 (§8.13.7, printed p.32) [VC]', verified_at=now() where id='eb5538bc-ed99-4e0d-a1f9-4b5d60923673' and verification_status not in ('verified_against_standard','corrected');
-- VDI-3814-Blatt-2-1-06 · gewerkespezifische_schnittstellen
update public.fields set verification_status='verified_against_standard', verification_quote='Im Rahmen der Bedarfsplanung empfiehlt es sich, detaillierte einheitliche Spezifizierungen der gewerkespezifischen Schnittstellen gemeinsam mit dem AG vorzunehmen und diese im weiteren Planungsprozess verfeinern zu lassen. [...] | Schnittstellendefinition im Gewerk A | Angaben vom Gewerk A an Gewerk B im Rahmen der Planung [...] | Lieferumfang Schnittstellengewerk A | Lieferumfang Schnittstellengewerk B | Koordinationsinhalte | Verantwortlichkeit | Gewährleistung | Dokumentation — printed p.32-33', verification_note='md-verified 2026-09-05 (§8.14, printed p.32-33) [VC] — the source is a recommendation ("empfiehlt es sich") — see STAGED file', verified_at=now() where id='ee0c29e7-e977-4717-9058-b5378bf11870' and verification_status not in ('verified_against_standard','corrected');
-- VDI-3814-Blatt-2-1-07 · anforderungen_pruefbar
update public.fields set verification_status='verified_against_standard', verification_quote='Im Lastenheft sind sämtliche Anforderungen aus Anwendersicht einschließlich aller Randbedingungen zu beschreiben. Die Anforderungen müssen quantifizierbar und prüfbar sein. — printed p.6', verification_note='md-verified 2026-09-05 (§6.1, printed p.6) [VC]', verified_at=now() where id='958f0ca8-83dc-4970-a46d-b3abdb567015' and verification_status not in ('verified_against_standard','corrected');
-- VDI-3814-Blatt-2-1-07 · lastenheft_vollstaendig
update public.fields set verification_status='verified_against_standard', verification_quote='Ein GA-Lastenheft wird grundsätzlich vom AG oder in seinem Auftrag (in der Regel unterstützt durch fachplanerische Kompetenz) vor Beginn einer Planung vollständig und widerspruchsfrei erstellt. — printed p.20', verification_note='md-verified 2026-09-05 (§8.1, printed p.20) [VC]', verified_at=now() where id='c701f6d2-d371-4c0b-9815-95e5e6aed588' and verification_status not in ('verified_against_standard','corrected');
-- VDI-3814-Blatt-2-1-07 · dokumente_gepflegt
update public.fields set verification_status='verified_against_standard', verification_quote='Die im Rahmen der Bedarfsplanung erstellten Dokumente, wie Betreiberkonzepte und Lastenhefte, sind durch den AG kontinuierlich zu pflegen und durch alle Verwender verpflichtend zu beachten. — printed p.5', verification_note='md-verified 2026-09-05 (§5, printed p.5) [VC]', verified_at=now() where id='c8a7f8c2-f0e4-4b66-996f-ccd02c77f5d8' and verification_status not in ('verified_against_standard','corrected');

